FindByName.example:
#include <cinux/container/name_table.hpp>

using namespace cinux::base::container;

struct DeviceTag {
    const char* name;
    unsigned long long word;
};

constexpr DeviceTag kTags[] = {
    {"console", 0},
    {"tty", 1},
    {"null", 2},
};

void Example() {
    constexpr auto* kTty = FindByName(kTags, "tty");  // kTty->word = 1 · 命中 tty 这一项
    static_assert(kTty->word == 1);
    static_assert(FindByName(kTags, "pty") == nullptr);  // 查不到时拿到空指针
}

FindByWord.example:
#include <cinux/container/name_table.hpp>

using namespace cinux::base::container;

struct IoctlTag {
    const char* name;
    unsigned long long word;
};

constexpr IoctlTag kIoctls[] = {
    {"TCGETS", 0x5401},
    {"TCSETS", 0x5402},
};

void Example() {
    constexpr auto* kSet = FindByWord(kIoctls, 0x5402);  // kSet->word = 0x5402 · 命中 TCSETS
    static_assert(kSet->word == 0x5402);
    static_assert(FindByWord(kIoctls, 0x9999) == nullptr);
}

cinux::base::container::StaticStack::pop.example:
#include <cinux/container/static_stack.hpp>

using namespace cinux::base::container;

void Example() {
    constexpr int kTop = [] {
        StaticStack<int, 4> stack;
        const bool kFilled = stack.push(11) && stack.push(22);  // true · 11 在下，22 在上
        int value = 0;
        const bool kPopped = stack.pop(value);  // kPopped = true，value = 22 · 后进先出
        return kFilled && kPopped ? value : -1;
    }();
    static_assert(kTop == 22);
}
